Subroutine DividirSeguro(a As Integer, b As Integer) As Result<Integer, String>
  If b = 0 Then
    Return Failure("No se puede dividir entre 0");
  EndIf
  Return Success(a Div b);
EndSubroutine

Algorithm Division
  Switch DividirSeguro(10, 0) Do
    Success(cociente): Write cociente;
    Failure(motivo): Write motivo;
  EndSwitch
EndAlgorithm

Function valido <- EsNumero(texto As String)
  Define desde As Integer <- 0;
  If length(texto) > 0 Then
    If charAt(texto, 0) = '-' Then
      desde <- 1;
    EndIf
  EndIf
  Define valido As Boolean <- length(texto) > desde;
  For i <- desde To length(texto) - 1 Do
    If Not contains("0123456789", toText(charAt(texto, i))) Then
      valido <- False;
    EndIf
  EndFor
EndFunction

Subroutine ValidarEdad(texto As String) As Result<Integer, String>
  If Not EsNumero(texto) Then
    Return Failure("no es un número");
  EndIf
  Define edad As Integer <- toInteger(texto);
  If edad < 6 Or edad > 18 Then
    Return Failure("fuera de rango");
  EndIf
  Return Success(edad);
EndSubroutine

Algorithm Inscripcion
  Define texto As String;
  Read texto;
  Switch ValidarEdad(texto) Do
    Success(edad): Write "Inscripción aceptada: ", edad;
    Failure(motivo): Write "Rechazada: ", motivo;
  EndSwitch
EndAlgorithm
